function armsHeroMeasure(panel) {
  const dialog = typeof panel.closest === 'function' && panel.closest('dialog');
  if (!dialog) return;
  const box = panel.querySelector('[data-arms-inspector]');
  const height = box.hidden ? 0 : Math.ceil(box.getBoundingClientRect().height);
  dialog.style.setProperty('--arms-inspector-height', height + 'px');
}
if (typeof window.addEventListener === 'function') window.addEventListener('resize', function () {
  document.querySelectorAll('#w-hero [data-arms-panel]').forEach(armsHeroMeasure);
});
